import{_ as l,a0 as p,w as o,s as h,ao as d,I as n,x as i,a1 as a,A as t}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const C=JSON.parse('{"title":"如何在 Linux 上讓一段時間不活動的用户自動登出 | LCTT x X-CMD","titleTemplate":false,"description":"如何在 Linux 上讓一段時間不活動的用户自動登出 | LCTT (201801) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在 Linux 上讓一段時間不活動的用户自動登出 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在 Linux 上讓一段時間不活動的用户自動登出 | LCTT (201801) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201801/20170916 How To Auto Logout Inactive Users After A Period Of Time In Linux","title":"如何在 Linux 上讓一段時間不活動的用户自動登出","tag":"201801","desc":""},"relativePath":"201801/20170916 How To Auto Logout Inactive Users After A Period Of Time In Linux.md","filePath":"[post].md"}'),r={name:"201801/20170916 How To Auto Logout Inactive Users After A Period Of Time In Linux.md"};function g(c,s,u,k,b,f){const e=p("Link");return o(),h("div",null,[s[13]||(s[13]=d(`<h1 id="如何在-linux-上讓一段時間不活動的用户自動登出" tabindex="-1">如何在 Linux 上讓一段時間不活動的用户自動登出 <a class="header-anchor" href="#如何在-linux-上讓一段時間不活動的用户自動登出" aria-label="Permalink to “如何在 Linux 上讓一段時間不活動的用户自動登出”">​</a></h1><p><img src="https://www.ostechnix.com/wp-content/uploads/2017/09/logout-720x340.jpg" alt=""></p><p>讓我們想像這麼一個場景。你有一台服務器經常被網絡中各系統的很多個用户訪問。有可能出現某些用户忘記登出會話讓會話保持會話處於連接狀態。我們都知道留下一個處於連接狀態的用户會話是一件多麼危險的事情。有些用户可能會藉此故意做一些損壞系統的事情。而你，作為一名系統管理員，會去每個系統上都檢查一遍用户是否有登出嗎？其實這完全沒必要的。而且若網絡中有成百上千台機器，這也太耗時了。不過，你可以讓用户在本機或 SSH 會話上超過一定時間不活躍的情況下自動登出。本教程就將教你如何在類 Unix 系統上實現這一點。一點都不難。跟我做。</p><h3 id="在-linux-上實現一段時間後自動登出非活動用户" tabindex="-1">在 Linux 上實現一段時間後自動登出非活動用户 <a class="header-anchor" href="#在-linux-上實現一段時間後自動登出非活動用户" aria-label="Permalink to “在 Linux 上實現一段時間後自動登出非活動用户”">​</a></h3><p>有三種實現方法。讓我們先來看第一種方法。</p><h4 id="方法-1" tabindex="-1">方法 1： <a class="header-anchor" href="#方法-1" aria-label="Permalink to “方法 1：”">​</a></h4><p>編輯 <code>~/.bashrc</code> 或 <code>~/.bash_profile</code> 文件：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ vi ~/.bashrc</span></span></code></pre></div><p>或，</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ vi ~/.bash_profile</span></span></code></pre></div><p>將下面行加入其中：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>TMOUT=100</span></span></code></pre></div><p>這會讓用户在停止動作 100 秒後自動登出。你可以根據需要定義這個值。保存並關閉文件。</p><p>運行下面命令讓更改生效：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ source ~/.bashrc</span></span></code></pre></div><p>或，</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ source ~/.bash_profile</span></span></code></pre></div><p>現在讓會話閒置 100 秒。100 秒不活動後，你會看到下面這段信息，並且用户會自動退出會話。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>timed out waiting for input: auto-logout</span></span>
<span class="line"><span>Connection to 192.168.43.2 closed.</span></span></code></pre></div><p>該設置可以輕易地被用户所修改。因為，<code>~/.bashrc</code> 文件被用户自己所擁有。</p><p>要修改或者刪除超時設置，只需要刪掉上面添加的行然後執行 <code>source ~/.bashrc</code> 命令讓修改生效。</p><p>此外，用户也可以運行下面命令來禁止超時：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ export TMOUT=0</span></span></code></pre></div><p>或，</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ unset TMOUT</span></span></code></pre></div><p>若你想阻止用户修改該設置，使用下面方法代替。</p><h4 id="方法-2" tabindex="-1">方法 2： <a class="header-anchor" href="#方法-2" aria-label="Permalink to “方法 2：”">​</a></h4><p>以 root 用户登錄。</p><p>創建一個名為 <code>autologout.sh</code> 的新文件。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># vi /etc/profile.d/autologout.sh</span></span></code></pre></div><p>加入下面內容：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>TMOUT=100</span></span>
<span class="line"><span>readonly TMOUT</span></span>
<span class="line"><span>export TMOUT</span></span></code></pre></div><p>保存並退出該文件。</p><p>為它添加可執行權限：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># chmod +x /etc/profile.d/autologout.sh</span></span></code></pre></div><p>現在，登出或者重啓系統。非活動用户就會在 100 秒後自動登出了。普通用户即使想保留會話連接但也無法修改該配置了。他們會在 100 秒後強制退出。</p><p>這兩種方法對本地會話和遠程會話都適用（即本地登錄的用户和遠程系統上通過 SSH 登錄的用户）。下面讓我們來看看如何實現只自動登出非活動的 SSH 會話，而不自動登出本地會話。</p><h4 id="方法-3" tabindex="-1">方法 3： <a class="header-anchor" href="#方法-3" aria-label="Permalink to “方法 3：”">​</a></h4><p>這種方法，我們只會讓 SSH 會話用户在一段時間不活動後自動登出。</p><p>編輯 <code>/etc/ssh/sshd_config</code> 文件：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo vi /etc/ssh/sshd_config</span></span></code></pre></div><p>添加/修改下面行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>ClientAliveInterval 100</span></span>
<span class="line"><span>ClientAliveCountMax 0</span></span></code></pre></div><p>保存並退出該文件。重啓 sshd 服務讓改動生效。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo systemctl restart sshd</span></span></code></pre></div><p>現在，在遠程系統通過 ssh 登錄該系統。100 秒後，ssh 會話就會自動關閉了，你也會看到下面消息：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ Connection to 192.168.43.2 closed by remote host.</span></span>
<span class="line"><span>Connection to 192.168.43.2 closed.</span></span></code></pre></div><p>現在，任何人從遠程系統通過 SSH 登錄本系統，都會在 100 秒不活動後自動登出了。</p><p>希望本文能對你有所幫助。我馬上還會寫另一篇實用指南。如果你覺得我們的指南有用，請在您的社交網絡上分享，支持 我們！</p><p>祝您好運！</p><hr>`,51)),n("p",null,[s[1]||(s[1]=i("via: ",-1)),a(e,{href:"https://www.ostechnix.com/auto-logout-inactive-users-period-time-linux/"},{default:t(()=>[...s[0]||(s[0]=[i("https://www.ostechnix.com/auto-logout-inactive-users-period-time-linux/",-1)])]),_:1})]),n("p",null,[s[5]||(s[5]=i("作者：",-1)),a(e,{href:"https://www.ostechnix.com/author/sk/"},{default:t(()=>[...s[2]||(s[2]=[i("SK",-1)])]),_:1}),s[6]||(s[6]=i(" 譯者：",-1)),a(e,{href:"https://github.com/lujun9972"},{default:t(()=>[...s[3]||(s[3]=[i("lujun9972",-1)])]),_:1}),s[7]||(s[7]=i(" 校對：",-1)),a(e,{href:"https://github.com/wxy"},{default:t(()=>[...s[4]||(s[4]=[i("wxy",-1)])]),_:1})]),n("p",null,[s[10]||(s[10]=i("本文由 ",-1)),a(e,{href:"https://github.com/LCTT/TranslateProject"},{default:t(()=>[...s[8]||(s[8]=[i("LCTT",-1)])]),_:1}),s[11]||(s[11]=i(" 原創編譯，",-1)),a(e,{href:"https://linux.cn/"},{default:t(()=>[...s[9]||(s[9]=[i("Linux中國",-1)])]),_:1}),s[12]||(s[12]=i(" 榮譽推出",-1))])])}const y=l(r,[["render",g]]);export{C as __pageData,y as default};
